/**
 * @file cla_pipeline_config.h
 * @brief CPU/CLA split of the CNN stages (1 = CLA, 0 = CPU).
 * @note Generated by ADOT on every export; do not edit.
 * @par Timing (model, not measured)
 * - Target: TMS320F28379D (C28x 200 MHz, CLA 200 MHz)
 * - Features: 1.20 ms (measured)
 * - Cycles/MAC: 9 CLA, 13 C28x (model), held-out error -0.0..+0.6% (-O0)
 * - S1: 1.163 ms on CPU, 18,144 MAC (other side 1.220 ms)
 * - S2: 2.284 ms on CLA, 52,488 MAC (other side 1.882 ms)
 * - S3: 0.054 ms on CLA, 1,296 MAC (other side 0.043 ms)
 * - Latency 4.70 ms, period 2.36 ms (CLA overlaps 2.338 ms)
 * - Inference is the longer half: 3.50 ms against 1.2 ms of feature extraction, so the network sets the pace. The current split is already the faster one: a window every 2.4 ms, against 3.6 ms with every stage on the CLA. That is 5% of the 51 ms window budget; fewer channels would shorten it further only if you need to.
 */
#ifndef CLA_PIPELINE_CONFIG_H
#define CLA_PIPELINE_CONFIG_H

#define CLA_STAGE_CONV1_POOL1  0 /**< S1: conv1 + ReLU + pool1. */
#define CLA_STAGE_CONV2_POOL2  1 /**< S2: conv2 + ReLU + pool2. */
#define CLA_STAGE_DENSE        1 /**< S3: dense layer. */

/** @brief All stages on the CLA: they run as one task. */
#define CLA_SINGLE_TASK  (CLA_STAGE_CONV1_POOL1 && CLA_STAGE_CONV2_POOL2 && CLA_STAGE_DENSE)
#define CLA_ANY_STAGE    (CLA_STAGE_CONV1_POOL1 || CLA_STAGE_CONV2_POOL2 || CLA_STAGE_DENSE) /**< Any stage on the CLA. */
#define CLA_TOUCHES_WORKSPACE  CLA_ANY_STAGE /**< CLA reads workspace[]. */

#endif
